      source_player_or_id = instance->targets[0].player;
      c = instance->targets[0].card;
      if (event == EVENT_CAN_ACTIVATE)
      {
        if (generic_activated_ability(player, card, EVENT_CAN_ACTIVATE, 0, 1, 0, 0, 0, 0, 0, 0,
                                      NULL, NULL) != 0)
        {
          return 1;
        }
