      }
      else if (event == EVENT_RESOLVE_ACTIVATION)
      {
        selected_mode = instance->targets[1].player;
        if (selected_mode == 0)
        {
          pump_until_eot_merge_previous(source_player_or_id, c, source_player_or_id, c, 1, 1);
