  {
    if (player == 0)
    {
      charge_mana(0, COLOR_ANY, -1);
      if (spell_fizzled != 1)
      {
        scnprintf(buffer, 500, "Select target creature card with CMC %d", x_value);
        new_default_test_definition(&test, 2, buffer);
        test.cmc = x_value;
        new_global_tutor(0, 0, 2, 4, 1, 1, &test);
      }
    }
    else if (-1 < zombie_position)
    {
