          grave_index = grave_index + -1;
          if (-1 < grave_index)
          {
            do
            {
              selected = graveyard[grave_index];
              id = cards_data[selected].id;
              if (id == CARD_ID_KOZILEKS_RETURN)
              {
                if ((triggers & 4) != 0)
