                    new_damage_all(player, selected, 2, 5, 1, NULL);
                    rfg_card_in_hand(player, selected);
                  }
                  else
                  {
                    obliterate_card(player, selected);
                    hand_count[player] = hand_count[player] + -1;
                  }
                }
