                      ((selected = duh_mode(player),
                        selected != 0 ||
                            (selected = do_dialog(player, player, card, -1, -1,
                                                  " Return Vengevine to play\n Do not return", 0),
                             selected == 0))))
                  {
                    reanimate_permanent(player, card, player, grave_index, REANIMATE_DEFAULT);
